CREATE COLUMN TABLE "TEST_AP"."ASTT" ("AbsId" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(40) NOT NULL , "UserSign" SMALLINT CS_INT, "IsVat" NVARCHAR(1) DEFAULT 'N', "NfTaxId" INTEGER CS_INT, "TpsId" INTEGER CS_INT, "PLABalance" DECIMAL(21,6) CS_FIXED, "Locked" NVARCHAR(1) DEFAULT 'N', "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "CreditCtrl" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("AbsId", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ASTT_NAME" ON "TEST_AP"."ASTT" ( "Name" ASC, "LogInstanc" ASC )